-- Run once using the MySQL database included in the existing plan. No CREATE DATABASE.
CREATE TABLE IF NOT EXISTS cf_users (id VARCHAR(64) PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password VARCHAR(255) NULL, photo MEDIUMTEXT NULL, google_sub VARCHAR(255) NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_sessions (token CHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, expires BIGINT NOT NULL, reauth_until BIGINT NOT NULL DEFAULT 0, INDEX(user_id), FOREIGN KEY(user_id) REFERENCES cf_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_consents (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,terms VARCHAR(64) NOT NULL,privacy VARCHAR(64) NOT NULL,accepted_at BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES cf_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_challenges (token CHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,kind VARCHAR(20) NOT NULL,payload VARCHAR(254),expires BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES cf_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_patients (id VARCHAR(170) PRIMARY KEY,owner VARCHAR(64) NOT NULL,local_id VARCHAR(100) NOT NULL,name VARCHAR(150) NOT NULL,snapshot MEDIUMTEXT NOT NULL,code CHAR(20) NOT NULL UNIQUE, FOREIGN KEY(owner) REFERENCES cf_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_members (patient VARCHAR(170) NOT NULL,user_id VARCHAR(64) NOT NULL,active TINYINT NOT NULL DEFAULT 1,PRIMARY KEY(patient,user_id), FOREIGN KEY(patient) REFERENCES cf_patients(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES cf_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_sync (user_id VARCHAR(64) PRIMARY KEY,revision BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES cf_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_batches (user_id VARCHAR(64) NOT NULL,batch VARCHAR(100) NOT NULL,PRIMARY KEY(user_id,batch), FOREIGN KEY(user_id) REFERENCES cf_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_notices (id VARCHAR(64) PRIMARY KEY,patient VARCHAR(170) NOT NULL,user_id VARCHAR(64) NOT NULL,record_id VARCHAR(100) NOT NULL,record_type VARCHAR(20) NOT NULL,type VARCHAR(40) NOT NULL,title VARCHAR(120) NOT NULL,created_at BIGINT NOT NULL,read_at BIGINT NULL, FOREIGN KEY(patient) REFERENCES cf_patients(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES cf_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_links (id VARCHAR(64) PRIMARY KEY,patient VARCHAR(170) NOT NULL,code_hash CHAR(64) NOT NULL, FOREIGN KEY(patient) REFERENCES cf_patients(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_files (id CHAR(64) PRIMARY KEY,patient VARCHAR(170) NOT NULL,owner VARCHAR(64) NOT NULL,record_id VARCHAR(100) NOT NULL,kind VARCHAR(20) NOT NULL,name VARCHAR(255) NOT NULL,mime VARCHAR(64) NOT NULL,size BIGINT NOT NULL,created_at BIGINT NOT NULL, FOREIGN KEY(patient) REFERENCES cf_patients(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_audit (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NULL,action VARCHAR(80) NOT NULL,target VARCHAR(170) NULL,created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cf_rate (bucket CHAR(64) PRIMARY KEY,hits INT NOT NULL,expires BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS cf_oauth (state CHAR(64) PRIMARY KEY,binding CHAR(64) NOT NULL,verifier VARCHAR(100) NOT NULL,payload TEXT NOT NULL,expires BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
